import nextWorker from "../../web/.open-next/worker.js";
import type { ExecutionContext } from "@cloudflare/workers-types";
import { app } from "./app";
import type { Env } from "./env";
import { handleQueue, handleScheduled } from "./jobs";

// @ts-ignore generated by the OpenNext build
export {
  DOQueueHandler,
  DOShardedTagCache,
  BucketCachePurge,
} from "../../web/.open-next/worker.js";

export default {
  async fetch(
    request: Request,
    env: Env,
    ctx: ExecutionContext,
  ): Promise<Response> {
    const url = new URL(request.url);
    if (url.hostname === "mimelie.vira.ia.br") {
      return nextWorker.fetch(request, env, ctx);
    }
    if (url.hostname === "painel-mimelie.vira.ia.br") {
      if (url.pathname.startsWith("/v1/")) {
        return app.fetch(request, env, ctx);
      }
      if (
        url.pathname === "/" ||
        url.pathname === "/admin" ||
        url.pathname === "/admin/"
      ) {
        return env.ASSETS.fetch(
          new Request(new URL("/admin/index.html", url), request),
        );
      }
      return env.ASSETS.fetch(request);
    }
    return app.fetch(request, env, ctx);
  },
  queue: handleQueue,
  scheduled: handleScheduled,
};
